type RawNodeTuple = readonly [
  id: string,
  x: number,
  z: number,
  district: DistrictId,
  hasTrafficLight: 0 | 1,
];

type RawEdgeTuple = readonly [
  from: string,
  to: string,
  name: string,
  roadType: RoadType,
  lanesPerDir: number,
  speedLimit: number,
  width: number,
  sidewalkWidth: number,
  isShortcut?: 0 | 1,
  isOneWay?: 0 | 1,
  roundaboutId?: string,
  roundaboutCenter?: readonly [number, number, number],
];

type RawBuildingTuple = readonly [
  x: number,
  z: number,
  w: number,
  d: number,
  h: number,
  rotY: number,
  color: number,
  roofColor: number,
  style: CustomBuildingStyle,
];

interface RawRampSpec {
  id: string;
  x: number;
  z: number;
  width: number;
  length: number;
  height: number;
  yaw: number;
  label: string;
}

